import math

def check_condition(n):
    """
    Checks if k^2 - 1 is divisible by n for all k such that 1 <= k < n and gcd(k, n) = 1.
    Returns True if the condition holds, False otherwise.
    """
    if n < 2:
        return False

    for k in range(1, n):
        if math.gcd(k, n) == 1:
            # Check if k^2 - 1 is divisible by n
            if (k*k - 1) % n != 0:
                # print(f"Failed for n={n}, k={k}. k^2 - 1 = {k*k - 1}, which is not divisible by {n}.")
                return False
    return True

solutions = []
for n in range(2, 31):
    if check_condition(n):
        solutions.append(n)

print(f"Solutions found: {solutions}")
